// Bir ders + sınıf için öğrenme çıktılarını döndürür.
export function getKazanimlar(ders: string, sinif?: number): Kazanim[] {
  const list = CURRICULUM[ders] ?? []
  return sinif ? list.filter((k) => k.sinif === sinif) : list
}
